import{_ as a,c as e,o as t,ah as i}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易经传集解卷三十","description":"周易经传集解 - 周易经传集解卷三十","frontmatter":{"title":"周易经传集解卷三十","description":"周易经传集解 - 周易经传集解卷三十"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/031.md","filePath":"zh/classics/jingchuan-jijie/031.md"}'),s={name:"zh/classics/jingchuan-jijie/031.md"};function n(c,p,r,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[i('<p>钦定四库全书</p><h1 id="周易经传集解卷三十" tabindex="-1">周易经传集解卷三十 <a class="header-anchor" href="#周易经传集解卷三十" aria-label="Permalink to “周易经传集解卷三十”">​</a></h1><p>宋林栗撰</p><p>序卦曰：「兑」者，说也。说而后取之，故受之以涣。「涣」者，离也。「涣」，「兑」之变也。自「兑」之「涣」，下变为「坎」，上反为「巽」，二、五不动而成也。下变为「坎」，则九二刚中，流而不盈，象所谓「刚来而不穷」也。上反为「巽」，则六四得位以承九五，彖所谓「柔得位而上同」也。夫所以为「兑」者，刚中而柔外也。以九居初，则刚而易穷；以六居上，则柔而失位也。是故「兑」之象为泽，泽以水聚为说者也。水聚而不流，则壅阏而为臭腐，枯渗而为涸竭矣。涸者，以其穷也；腐者，以其失位也。决而为「坎」，则刚来而不穷；反而为「巽」，则柔同而得位，所以为「涣」也。「涣」，散也，离也。人情喜说，则血气流通，离散于四体而无所凝滞，是以谓之「涣」也。天下之势，譬如一身，既已心说而诚服矣，虽散之四方万里之远，如居几甸之中，可杀可辱，可饥可饱，而不可与叛其君，是则说而后散之之义也。「坎」为水，「巽」为风。风行水上，水冻消释，舟楫通行，「涣」之象也。「涣」之「坎」、「兑」，不其然乎？</p><p>「涣」：亨，王假有庙，利涉大川，利贞。彖曰：「涣，亨」，刚来而不穷，柔得位乎外而上同。「王假有庙」，王乃在中也。「利涉大川」，乘木有功也。</p><p>下坎上巽，成卦曰「涣」者，初为坎，二为震，三为艮，四为巽。坎，北方也；震，东方也。艮，东北也；巽，东南也。一阳生于「坎」，而六阳盛于「巽」，阳气周流乎其中，卦之所以为「涣」也。涣者，散也。人之血气涣散，则其身安；国之政令流通，则其国治。故曰：「涣，亨。」而子曰：「涣，亨，刚来而不穷，柔得位乎外而上同。」释所以亨之义也。夫所以为「坎」者，九二也。所以为「巽」者，六四也。以九居二，则刚来而不穷。以六居四，则柔得位乎外，而上同于九五也。刚来而不穷，德之所以流行也。柔得位乎外，令之所以布宣也。上同于五，君臣合志而上下同心也。如是而「亨」，不亦宜乎。「王假有庙，利涉大川，利贞。」何谓也？曰：假，大也。「王假有庙」者，非诸侯之所得有也。九五者，王之所居，而庙之所在乎？或曰：「萃、涣二卦，言王假有庙。萃，聚也；涣，散也。聚散不同，而有庙之义同，何也？」曰：天下萃聚而有君，然后王庙可以建；天下涣散而无事，然后王庙可以居。是故萃之庙在四，而涣之庙在五，各应其时义也。说者皆袭焦延寿之论，以上爻为宗庙。愚谓不然。宗庙者，国之本也，其在都邑之中矣。涣自五而下，有庙之象焉。故彖言王庙，而九五言「王居，明其所在也。延寿之论疏矣。」或曰：「庙在王居，则萃之在四，何也？」曰：「萃之时，王者方受天下之萃，可以致其孝享，而都邑未定，宗庙未立，故虽以九居五，有位而未光。然则庙之在四，宜矣。及涣之时，天下涣然各得其所，王者于是建都立邑，辨方正位，创其宗庙，作其宫室，以为子孙万世之图，是以系之九五也。昔周武王至于孟津，八百诸侯不期而会，斯之谓萃矣。王来自商，至于丰，归马于卒山之阳，放牛于桃林之野，列爵惟五，分土惟三，斯之谓涣矣。是故合而为一统，离而为万邦，聚而为军师卒伍，散而为士农工商，萃涣之别也。说者乃以散离之辞，为土崩瓦解之义，不亦以文害辞，以辞害意之甚者乎？」或曰：「然则有天下者，玉食万方，萃有其象，而至于庙，则五而已。王假有庙，于何而取之？」曰：「夫子不云乎，王假有庙，王乃在中也。言自五以下，有七庙之象，而九二者，王在宗庙之中，致孝于神明之象也，不其然乎？」或曰：「九五，王也，二亦为王，何哉？」曰：「由天下归往而言之，则五为王；由宗庙祭祀而言之，则二为王。五为王者，宅中之象也；二为王者，致孝之象也。」夫岂一端而足哉？是故五为「震」，二亦为「震」。「震」，长子而帝之出也。居五以临天下，居二以事其先，斯为得之矣。其言「利涉大川」，则取诸坎巽也。坎为水，巽为风，以风乘木而行于水上，其「利涉」之象与？系曰：刳木为舟，剡木为楫，舟楫之利，以济不通，盖取诸涣，以其义也，「利贞」，何也？贞者，正也。天下涣然，必有持正者。莫为之正者，离散而无所统一，非「涣」之义矣。是故九五正位居中，而天下各得其所，斯「利贞」之谓与！或曰：子以阴阳往复，取诸夏时，则既有征。今又曰：「一阳生于坎，而六阳盛于巽，何谓也？」曰：是何言与？六经之道，天人之理，无所不该，而况易之为书，又其至者。穷壤之间，苟有是理，圣人乌得而遗之？顾乾、坤、复、姤之配，取诸离、坎，不应象类，愚是以辨之。若蛊之「先甲」「后甲」，盖取诸坎；而巽之「先庚」「后庚」，亦取诸离。圣人于蛊、剥、复三卦，皆言「天行」以释之。然则一阳生于坎，而六阳盛于巽，又岂穿凿而为矛盾之论哉？学者谨马可矣。象曰：风行水上，「涣」，先王以享于帝，立庙。</p><p>风者，「巽」也；水者，「坎」也。巽不取诸木而取诸风者，木浮于水，无以明「涣」之象。惟风行水上，而后涣之象可见矣。风行水上，水自动摇，风作于此，水散于彼，故先王以之享帝立庙。享帝以教钦，立庙以教爱，而民自化服矣。若风行地上，风至而后草偃，故先王以之省方观民而设教焉。盖相因而取象也。当天下涣然无难之时，享帝立庙，适其宜矣。杂卦曰：「涣，离也。」</p><p>涣之为卦，以风行水散而成。其在六爻，以血气涣离为义。风者，气也。水者，血也。血气所以荣卫其身也。循于经络，行于腑脏，昼夜不息，与天共地，相为流通，然后身安而无疾。若有所壅隔而不离，则疾之所由生也。是故涣与咸艮，皆以爻位分配人之一身。然咸艮之义，取喻人之形体。形体分布于外，故其象显，其辞明。涣之义，取喻人之气血。气血周流于内，故其象隐，其辞晦。然学者不可不深求其指归也。气属乎阳，血属乎阴，阳气行则血气俱行，阳气滞则血气俱滞。是故「涣」之诸爻，以阳居柔者，是血气之所行也；以阴居刚者，是血气之所滞也；以阳居刚、以阴居柔者，是血气之所归藏也。全「涣」之体，有身之象焉。中四爻以二阳包二阴，身腹之象也。奇画在上，偶画在下，首足之象也。初六言「拯」，九二言「奔」，六三言「躬」，六四言「群」，九五言「汗」，上九言「血」，各随其所在而别之矣。初六：用拯马壮，吉。象曰：「初六」之「吉」，顺也。</p><p>初六，坎也，以阴居刚，而在下卦之下，上无其应，而承于九二之震，故曰：「用拯马壮，吉。」「拯」，救拔也。「坎」为陷，震为动，故有「用拯」之象。「坎」为马，为曳，震为马，为作足，故有「马壮」之象。初六以阴在下，宜取象于足，谓其体坎而承震，震为足，是以系之用拯也。拯于险难之中，而得马壮，然后可以奔其机矣。故初六在「咸」言「拇」，在「艮」言「趾」，而「涣」但言「用拯」，不以形体言之也。「拇」，取其动也；「趾」，取其止也。「涣」之初六，始乎止而卒乎动，故但言「用拯」，而拇趾之象著矣。咸「艮」在下，有二阴，故初言「咸趾」，二言「腓」。「涣」惟一阴，故但言「用拯」，而「腓」之象亦兼矣。自二至上爻皆言「涣」，而初独不言者，谓其方拯而未离于难也。故子曰：「初六之吉，顺也。」当「涣」之初，柔顺而居下，故能自出于险陷之中，又得马壮以行之，斯为吉矣。「明夷」六二以「坎」承「震」，其辞曰：「用拯马壮，吉。」而子曰：「六二之吉，顺以则也。」与此象同。九二，涣奔其机，悔亡。象曰：「涣奔其机」，得愿也。</p><p>九二，震也。以阳居柔，而在下卦之中，上无其应，而介于二阴之间。二爻皆坎，而三又艮也，故曰「涣奔其机」。震为动，坎为险，故有奔其机之象。夫奔者以足，涣之足在下，而二言奔，何也？曰：初六之足弱而陷，九二之马壮而动，故初言拯而二言奔，相因而成义矣。然则九二之所以能奔者，其惟阳气之所在乎？「机」，旧读为「几」，人之所凭以为安者也。愚谓不然。夫人出于险陷之中，而履以平夷之地，斯以为安矣，而何至于凭几然后为安乎？若凭几然后为安，非痿则痹矣。按经典「几」字无从「木」者。说文曰：「机，木名。」愚谓「机」当作「机」。机，不安也。书曰：「邦之机陧。」机与祪同。奔其机者，奔去其不安之地也，故曰「悔亡」。夫吉凶悔吝生乎动，九二动于险陷之中，能无悔乎？谓其去臲□而适乎易之涂，斯为「悔亡」矣。故子曰：「涣奔其机，得愿也。」夫离险而就易，去危而即安，岂非人情之愿也哉？彖之所谓「刚来而不穷」者也。</p><p>六三：涣其躬，无悔。象曰：「涣其躬」，志在外也。</p><p>六三上体为「艮」，下体为「坎」，以阴居刚，而在下卦之上，应乎上九之「兑」，故曰「涣其躬」。「躬」者，身也。「涣」者，「离」也。「坎」为陷，「艮」为止，「兑」为毁折，故有「涣其躬」之象。夫所取于「涣」者，谓其血气周流于身，而无所壅滞也。居下体之上，在一卦之中，是血气之海也，而「涣」之何哉？有所止者，有所陷，有所毁折，是将离去其身矣。筋挛而不随，肌痹而不仁，气脱而不收，血亡而不复，皆「涣其身」者也，故曰「无悔」。「离」，共身矣，虽复悔之，其能有救哉？故子曰：「涣其躬，志在外也。」夫一身之政听命于心，一家之政听命于长，一国之政听命于君，天下之政听命于王。是故血气涣而不离于身，臣命涣而不离于国者，其志在内而无外交者也。当「涣」之时，上有九五为「涣」之主，而六三之志独应于上，「艮」「兑」相与，有陷上毁折之象焉，是将志于外而离其君者也。离其君者，离其国也；离其国者，离其身也。系之「无悔」，宜哉！</p><p>六四：涣其群，元吉。涣有丘，匪夷所思。象曰：「涣其群，元吉」，光大也。</p><p>六四上体为巽，下体为艮，以阴居柔而在上卦之下，下无其应，而承于九五之震，故曰「涣其群」。群，类也。四之于三，其画皆柔，其体皆「艮」，其类群矣。然三以艮而应于「兑」，四以「巽」而合于「震」，是以谓之「涣其群」也。「涣其群」者，犹「坤」之「丧朋」，大有之「匪其彭」也，故曰「元吉」。臣无有淫朋，人无有比德，斯之谓「元吉」矣。彖之所谓「柔得位乎外而上同」者也。近取诸身，其五脏六腑之谓与？五脏六腑各司其局，气血周流，无所砥滞，是以系之「元吉」也。故曰「溪有邱」。涣，散也。邱，聚也。夫「涣」也者，必有其聚者也。无聚而「涣」，则其涸可立而侍也。阳为气，阴为血。六四者血之所聚，而九五者，气之所藏也。气有所往，而血从之，四之所以上同也。故曰「匪夷所思」。思者，心也。夷者，类也。心之官则思，而非丑夷之思也。「涣其群」、「匪其夷」者，以所听于心者也。是故六三为躬，六四为群。躬有四肢，群有腑脏。四肢之譬，则公侯伯子男也。腑脏之譬，则卿士大夫也。公侯伯子男不可以离于国，离于国则叛也。卿士大夫不可以不散其朋，不散其朋则党也。此三、四之所以异也。传有之曰：「文王观于国，则列士坏植散群，长官者不成德。」则六四「涣其群」之谓也。至于庾斛不敢入于四境，诸侯无二心，则非所谓「涣其躬」矣。故子曰：「涣其群，元吉，光大也。」光大之辞，为九五言之也。五「涣其汗」，四「涣其群」，五之所以光大也。「咸」以九四为心，故其辞曰「朋从尔思」，而子曰「未光大也」，明四非中正之谓也。「涣」以九五为心，其辞曰「匪夷所思」，而夫子则系之以「光大之辞」，明五得中正之位也。「涣」之时义若此，说者但以为离险释难之卦，则是以「涣」为解者也。知其一而昧其二，得于初而失于终也。其或以为流离荡析之卦，则是以「涣」为剥者也。是谓指东为西，指白为黑也。又或兼二说而两取之，则是薰莸不辨而并称，冰炭无分而同谓也。呜呼！惜哉！</p><p>九五：涣汗其大号。涣，王居，无咎。象曰：「王居无咎」，正位也。</p><p>九五，震也。以阳居刚，而在上卦之中，下无其应，而乘乎六四之「巽」，故曰：「涣汗其大号。」震为动，为雷；巽为入，为风，故有「涣号」之象。夫九五者，王之所居，而庙之所在也。宅中图大，号令之所自出也。近取诸身，其神明之舍乎？心之液为汗，而王之命为号，是以取诸「涣汗」而谓之火号也。五脏之液，惟汗为能宣通，则以其出于心而周浃而四体故也。「涣其汗」，则血气流通而身安；「汗其号」，则政教流通而天下治矣。汉刘向有言：「涣汗其大号，汗出而不反者也。」其在书曰：「令出惟行。」不惟汲取诸涣汗，不亦可乎？故曰：「涣，王居，无咎。」以九居五，其位在中，故有王居之象。当涣之时，万物皆「涣」，而王独居中，不应涣义，疑若有咎矣。然天下既涣，贵乎利贞以居之。王正在位而涣其号，是以居中而无咎。故子曰：「王居无咎，正位也。」二爻重言「涣」者，皆谓「涣」是散离之义，而六四以阴居柔，九五以阳居刚，又有震巽之合焉，故四言「有邱」，而五言「王居」，疑若不应时义，是以申其文以发其旨也。自二至五，有身腹之象，二为震，五亦为震，明阳气之动，上下流动，故血气之行无所偏滞也。或曰：阳为气，阴为血，子以二五明阳气之动，而血气同称，何也？曰：阳气行则血与气俱行，阳气滞则血与气俱滞，岂得独言气而不言血乎？犹之为国，有教有刑，刑主乎义，教主乎仁，而其行之与否，均系乎德之存亡也，岂可谓唐虞三代有教而无刑乎？</p><p>上九，涣其血，去逖出，旡咎。象曰：「涣其血」，远害也。</p><p>上九，兑也。以阳居柔而在上卦之上，应乎六三之艮，而乘乎九五之震，故曰「涣其血去逖出」。三有坎体，坎为血，为忧伤。艮为止。震为动，为决。兑为说，为毁折，故有「血去逖出」之象。「逖」当作「愓」，与小畜六四之辞同。今本多作「逖」，非也。上九于身，为耳目鼻口之所在也。耳目鼻口，腑脏之外候，阳气之会，精华之所发也。然下与六三有艮兑相与之情，陷而止焉，是身之病也。其荣卫否隔而不通，则其精华消耗，动于外候，耳目将为之聋盲，鼻口将为之瘖寒，聚而为痈疽，结而为痼瘿，皆血气之壅滞也。是必涣散其血，血去而愓出，斯为「旡咎」矣。夫血者，所以荣于内，而不可涣于外者也。惟瘀败之血为害于身，则不可不涣耳。坎为忧伤，为心病，则败血也，可不涣乎？故曰「旡咎」。而子曰：「涣其血，远害也。」说者以「远害」之文，讹「惕」为「逖」，则失之矣。上之所以能涣其血者，阳气存焉故尔。血遇寒则止，得热则行，是以至于上九而后涣也。涣其血者，汤艾铁石之功也。远其害，则刑罚征诛之力也。刑罚征诛，有国者之所不得已也。或曰：子不以正爻为宗庙，则上九之位，谁当居之？曰：初、上者，始终之义也。其初难知，其上易知，本末也。其在六三，则「涣其躬」；其在上九，则「涣其血」者，九五已正其位故也。夫子于「乾」之上九曰「贵而无位」。夫岂以人鬼相杂而后成卦乎？苟如延寿之论，则宗庙之爻而有「血去」「惕出」之文，是何义也？施于「王假有庙」之卦，已不能通，况其余乎？序卦曰：涣者，离也。物不可以终离，故受之以</p><p>节。</p><p>节，「涣」之反也。自「涣」之「节」，坎反居上，「巽」反为「兑」，二五不动而成也。坎为水，「巽」为风，风行水上，则水动而散，是以谓之「涣」也。水行泽上，则泽得其节，是以谓之「节」也。说者皆以泽能止水，故谓之「节」。愚谓不然。夫「兑」之未重也，固以为止水之象矣。若「节」之成卦，但取止水为义，则理穷于「兑」，不得复有节象矣。而况以「坎」重兑，安得以一泽尽其义乎？且泽既止水矣，泽上安得有水乎？「困」之成卦，上兑下坎，宜曰「泽中有水」，而其象曰「泽无水」者，为其既重矣，嫌于无别也。况泽上水，安得但取止水为义乎？故「兑」之为「涣」也，泽决为川，而风木行于其上也。「涣」之为节也，水归于泽，而为之水道，以节其盈虚也。此泽上之所以有水，「坎」、「兑」之所以为节，而节之所以次「涣」也。</p><p>节：亨，苦节不可贞。彖曰：「节，亨」，刚柔分而刚得中。若「节不可贞」，其道穷也。说以行险，当位以节，中正以通。天地节而四时成，节以制度，不伤财，不害民。</p><p>下兑上坎，成卦曰「节」者，初为兑，二为震，三为艮，四为坎。兑，泽也；坎，水也。泽也者，水之聚也。泽之上而为水焉，是泛溢之象也，而谓之节，何哉？为其有震、艮之象焉。震为木，艮为土，泽水之际而施土木焉，是隄防之象也。震为决，艮为止，泽上有水，时决而出，时闭而止，是沟洫之象也。设为隄防，导为沟洫，则水得其节，是以谓之节也。「节，亨，苦节不可贞」，何谓也？曰：水无节则泛，政无节则荡。节以隄防，则水循其理；节以制度，则政得其宜。故曰：「节，亨。」节之所以亨者，刚柔分而刚得中也。在卦六爻，奇耦各居其半，刚柔分也。阳居二五，刚得中也。夫所以为节者，以刚柔宽猛不得其平矣。太刚则臲，太柔则坏，宽则民慢，猛则民残。是故刚柔分而不偏，刚得中而不过，所以能节而通也。或曰：刚虽得中，而柔不得中，可以为节乎？曰：节之成卦，取诸水也，刚而动者也。水由地中行，则无泛滥怀襄之患，是之谓「刚得中」矣。刚得中则节道成矣，岂柔之问哉？故曰：「苦节不可贞。」贞者，正也，以此为政者也。节之得中，则受节者乐而甘；节之过甚，则受节者艰而苦。节而至于苦，物情所不能堪，岂可常也哉？故子曰：「节，亨，刚柔分而刚得中。苦节不可贞，其道穷也。」夫子既释彖辞，又从而申之曰：「说以行险，当位以节，中正以通。天地节而四时成。节以制度，不伤财，不害民。」夫险者，人之所畏也，惟说以行之，则民从之矣。下兑上坎，所谓「说以行险」者与？「当位而节」，谓六四也。「中正以通」，谓九五也。苟能当位以节，中正以通，又何苦之有哉？天地之节，寒暑是也。寒极则暑，暑极则寒，四时之所以成也。节以制度，财用是也。国奢则示之以俭，国俭则示之礼，财之所以不伤，而民之所以不害也。国之政刑，无非节者，而独言「财用」，盖用之不节，有国者之通患也。</p><p>象曰：泽上有水，「节」，君子以制数度，议德行。泽者，「兑」也。「水」者，「坎」也。水之瀳至，其流有常，故君子以之常德行，习教事。泽上有水，其出有节，故君子以之「制数度，议德行」。虚则纳之，满则泄之，止而不穷，流而不盈，水之节也。直而温，柔而立，恭而不劳，谨而不蕙，德之节也。宽以济猛，猛以济宽，礼中通而不离，乐和正而不流，政之节也。至于律度、量衡、宫室、车舆、衣裳、冕弁、冠婚、丧祭，莫不有数有度，皆节之道也。程氏曰：「凡德之大小、轻重、高下、文质，皆有数度。存诸中为德，发诸外为行。议以求中节也。」耿氏曰：「伯夷之清，柳下惠之和，则亦不中其节，在所议矣。」杂卦曰：节，止也。</p><p>节之为卦，以泽上有水而成。其在六爻，以水得其止为义。夫水之在宅，以滋养灌溉为功者也。有所止则为功，无所止则为害。设为隄防，导为沟洫，视其潦旱而出纳之，察其盈虚而增损之。敛而不至于溢，散而不至于穷，所以为节止之道也。阳为刚，阴为柔；阳为动，阴为静。阳为实，阴为虚。阳为气，阴为形。故井以三阳为泉，三阴为井。节以三阳为水，三阴为防。水也，泉也，刚而动，气而实者也。井也，防也，柔而静，形而虚者也。水土之德，盖如是矣。夫所以为节，节其过与不及，使之适中而止也。九五有「甘节」之吉，六四有「安节」之亨，所谓当位以节，而中正以通者也。初九在下，故「不出」而「旡咎」；上六已极，故「道穷」而真「凶」。所谓「苦节不可真」者也。若夫九五之水，乱于六三之防。乱于水，则水壅而防溃故也。九二之「凶」，六三之「嗟」，斯其义矣。</p><p>初九：不出户庭，旡咎。象曰：「不出户庭」，知通塞也。</p><p>初九，兑也。以阳居刚，而在下卦之下，应乎六四。四，坎艮也，故曰「不出户庭」。说文曰：「户，护也。半门为户。」按古人门户通称，然对敌而言，则门为大而户为小，门为外而户为内矣。户庭，内庭也。「兑」为门户，其应在艮。艮，止也。上山下泽，无感应相与之情，而有惩忿窒欲之象，是以知其不出也。兑为口舌，故以言语为义。子曰：「古者言之不出。」又曰：「以约失之者鲜矣。」故曰「旡咎」。礼：「外言不入于梱，内言不出于梱。」户庭之言，梱内之言也。谨而不出，夫何咎之有哉？故子曰：「不出户庭，知通塞也。」泽居最下，宜塞而未宜通；及其既盈，宜通而不宜塞也。系曰：「乱之所生也，则言语以为阶。君不密则失臣，臣不密则失身，机事不密则害成。」是以君子谨密而不出也，其当塞之时乎？</p><p>九二：不出门庭，凶。象曰：「不出门庭，凶」，失时极也。九二，「震」也。以阳居柔而在下卦之中，旡其应而承于六三。三，「艮」也，「巽」也，故曰「不出门庭」。震为出，为门庭。巽为入，艮为止，故亦有「不出门庭」之象。门庭，外庭也。谋之于内庭，则不出于旡咎矣；宜之于外庭而不出焉，是今不行于近也，而况于四方万里之远乎？故曰「凶」。人君之德泽号令不能出于门庭，则或害之矣，欲无凶，得乎？故子曰：「不出门庭，凶，失时极也。」九二之水已震乎泽中，又从而止焉，失其时极矣。或曰：说卦「艮为门阙」，而子言「兑为门户，震为门庭」，何也？曰：兑上一阴，在人为口舌，在宫室为门户矣。震之二阴，门之象也。艮上一阳有观关之象，于阖辟何取哉？故兑为口舌，而震为善鸣，兑为户庭，而震为门庭，相因而成象也。明夷之三亦体震，而四有坎离之象，故其辞曰：「出门庭而相见乎离」也。节之二三，有震巽之合，而遇艮止焉，是以系之「不出门庭」也。六三之艮为门阙，九二之震为门庭，初九之兑为门庭矣。震为辟户，兑为阖户，宜阖而止，是以旡咎；宜辟而止，是以「凶」也。岂不然哉？</p><p>六三：不节若，则嗟若，旡咎。象曰：「不节」之「嗟」，又谁咎也。</p><p>六三上体为艮，下体为巽，以阴居刚而在下卦之上，上旡其应，而乘于九二之震，故曰：「不节若则嗟」。艮为土，为止，巽为入，震为动，故有「不节」之象焉。节者，隄防之谓也。阳为水，阴为防。防者，所以制水也。故防在水上，水不至焉；水在防下，防不入焉。今九二以阳居柔，六三以阴居刚，是阳与水相混者也。水出于防而入于水也。传曰：「水壅则溃，伤人必多。」九二之水动乎下，六三之防止于上，而不知所以宣导之，至于溃裂，故荡而不可节，贞者何嗟及矣，故曰「旡咎」。子曰：「不节之嗟，又谁咎也？」</p><p>六四：安节，亨。象曰：「安节」之「亨」，承上道也。</p><p>六四上体为坎，下体为艮，以阴居柔而在上卦之下，应于初九之兑，而承于九五之震，故曰「安节」。坎为水，为陷；艮为山，为止。止者，隄防之象也；陷者，沟洫之象也。设为隄防而导其沟洫，水者所以安行而受其节也。兑为说，震为行，坎为险。说以行险，是以知其「安节」矣，故曰「亨」。子曰：「安节」之亨，承上道也。上谓九五，九五水也。水在泽上，则六四者岂非承水之道乎？居近君之位，得承上之道，顺物之性，安而节之，此其所以「亨」也。</p><p>九五：甘节，吉，往有尚。象曰：「甘节」之吉，居位中也。</p><p>九五，「震」也。以阳居刚而在上卦之中，下旡其应，而介于二阴之间，二爻皆「坎」，而四又「艮」也，故曰「甘节」。「甘」，中央之味也。书曰「稼穑作甘」是也。「坎」为水，「艮」为土，「震」为耕稼，而五得中行，故有「甘节」之象。夫节以制度，人情之所不乐也。节而至于甘，则节之功见矣，故曰「吉」。又曰「往有尚」。「往有尚」者，「坎」之所以为功也。夫所以设为隄防，导为沟洫，以时而出纳之者，所以为水旱之备也欤！上六有炎上之苦，而九五以甘济之，是谓「往」而「有尚」也。体乎中正，行于险中，以成稼穑之功，斯为吉矣。故子曰：「甘节之吉。」「居位中」云者，水由地中行也。六四为承上道，九五为居位中，则泽上有水，其义粲然矣。</p><p>上六：苦节，贞凶，悔亡。象曰：「苦节，贞凶」，其道穷也。</p><p>上六，「坎」也。以阴居柔而在上卦之上，下无其应，而乘于九五之震，故曰「苦节」。「苦」，炎上之味也。「坎」之穷为「离」，六四既为「坎」矣，上六居卦之穷，是以有炎上之味也。润泽之所不及，而「离」日暵之，故其味焦而苦也。节而至于苦，物情所以不堪，故曰「贞凶」。以此为正，则凶矣。然而乂系之以「悔亡」，何谓也？上六，节之穷也，穷则变矣。节而至于苦，贞之则凶，变之则悔亡。下无其应，而乘于九五，五以中正与之为配，刚柔相资，甘苦相济，虚实相辅，故其悔至于亡也。阳为德，阴为刑。水譬则法禁也。以法禁裁惠泽，犹以数度议德行也。庆赏施惠，人之所欲，故谓之甘；刑威法禁，人之所畏，故谓之苦。以甘济苦，和羹之谓也。「悔亡」，不亦宜乎？说者或谓节有戒饮食之义，世人嗜甘而不嗜苦，故甘节为吉，而苦节为凶。愚谓节甘如前说可矣，节苦者何遽至于凶乎？夫节之为义，节其出也，非节其入也。此说似是而非，故辨而正之。子曰：「苦节贞凶，其道穷也。」九二在中而非中，上六居正而非正，然后君子知大中至正之所在矣。周易经传集解卷三十，</p>',35)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
